solutions.naive:
class Solution:
    def reverseWords(self, s: str) -> str:
        words = []
        i = 0
        while i < len(s):
            while i < len(s) and s[i] == ' ':
                i += 1
            start = i
            while i < len(s) and s[i] != ' ':
                i += 1
            if start < i:
                words.insert(0, s[start:i])  # Front insertion shifts existing words.
        return ' '.join(words)

