class Solution:
    def reverseWords(self, s: str) -> str:
        result = []
        i = len(s) - 1
        while i >= 0:
            while i >= 0 and s[i] == ' ':
                i -= 1
            end = i
            while i >= 0 and s[i] != ' ':
                i -= 1
            if i < end:
                result.append(s[i + 1:end + 1])
        return ' '.join(result)

